CREATE TABLE eforms_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organisation_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(organisation_id) REFERENCES organisations(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(organisation_id,status),CHECK(status IN ('draft','published','inactive'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE eforms_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_id BIGINT UNSIGNED NOT NULL,version INT UNSIGNED NOT NULL,schema_json LONGTEXT NOT NULL,workflow_json TEXT NOT NULL,allow_self_approval TINYINT NOT NULL DEFAULT 0,acknowledgement TEXT NOT NULL,checksum CHAR(64) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(template_id,version),FOREIGN KEY(template_id) REFERENCES eforms_templates(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE eforms_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,version_id BIGINT UNSIGNED NOT NULL,organisation_id BIGINT UNSIGNED NOT NULL,applicant_id BIGINT UNSIGNED NOT NULL,payload_cipher LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',step_index INT UNSIGNED NOT NULL DEFAULT 0,revision INT UNSIGNED NOT NULL DEFAULT 1,acknowledged_at DATETIME NULL,acknowledgement_hash CHAR(64) NULL,submitted_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(version_id) REFERENCES eforms_versions(id),FOREIGN KEY(organisation_id) REFERENCES organisations(id),FOREIGN KEY(applicant_id) REFERENCES users(id),INDEX(organisation_id,status),INDEX(applicant_id,status),CHECK(status IN ('draft','submitted','approved','rejected','returned'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE eforms_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,submission_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,action VARCHAR(40) NOT NULL,reason VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(submission_id) REFERENCES eforms_submissions(id),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX(submission_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE eforms_attachments(submission_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(40) NOT NULL,document_id BIGINT UNSIGNED NOT NULL UNIQUE,PRIMARY KEY(submission_id,field_key),FOREIGN KEY(submission_id) REFERENCES eforms_submissions(id),FOREIGN KEY(document_id) REFERENCES documents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
